INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(11901, 'Job 1:18', 'Job', 1, 18, '&nbsp;کله چې هغۀ لا خبرې کولې، نو يو بل کس راغلو او وې وئيل، ”ستا زامنو او لوڼو د خپل مشر ورور په کور کښې خوراک څښاک کولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11902, 'Job 1:19', 'Job', 1, 19, '&nbsp;چې ناڅاپه د صحرا د طرف نه يوه لويه هوا راغله او دې هوا د کور څلور واړه ګوټونه وخوځول او کور ستا په بچو باندې راوغورزېدو او هغوئ مړۀ شول، يواځې زۀ ژوندے پاتې يم چې تا خبر کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11903, 'Job 1:20', 'Job', 1, 20, '&nbsp;نو بيا ايُوب پاڅېدو، خپله چُوغه يې وشلوله، خپل سر يې کل کړو او په زمکه باندې يې سجده ولګوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11904, 'Job 1:21', 'Job', 1, 21, '&nbsp;هغۀ وفرمائيل، ”زۀ د مور نه خالى لاسونه پېدا وم او خالى لاسونه به د دې دُنيا نه ځم، هر څۀ ما له مالِک خُدائ راکړى وُو او مالِک خُدائ رانه واپس واخستل، د مالِک خُدائ د نوم ثناء صِفت دې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11905, 'Job 1:22', 'Job', 1, 22, '&nbsp;د دې هر څۀ باوجود ايُوب په خُدائ پاک د اِلزام لګولو ګناه ونۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11906, 'Job 2:1', 'Job', 2, 1, '&nbsp;يو ځل آسمانى مخلوق راغلو چې خپل ځانونه د مالِک خُدائ په مخکښې حاضر کړى او شېطان هم د هغوئ سره راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11907, 'Job 2:2', 'Job', 2, 2, '&nbsp;مالِک خُدائ شېطان ته وفرمائيل، ”تا څۀ کول؟“ نو شېطان ووئيل، ”زۀ په زمکه ګرځېدم راګرځېدم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11908, 'Job 2:3', 'Job', 2, 3, '&nbsp;نو مالِک خُدائ شېطان ته وفرمائيل، ”ستا زما د خِدمت کوونکى ايُوب په باره کښې څۀ خيال دے؟ په زمکه باندې د هغۀ په شان هيڅ څوک هم نشته، هغه يو بې‌داغه او نېک سړے دے چې هغه د خُدائ پاک نه يريږى او د بدۍ نه ځان ساتى. هغه تر اوسه پورې په خپل صداقت کښې قائم دے، اګر چې تا زۀ د هغۀ خِلاف لمسولم، چې بغېر د څۀ وجې نه يې په غضب آخته کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11909, 'Job 2:4', 'Job', 2, 4, '&nbsp;بيا شېطان مالِک خُدائ ته ووئيل، ”خلق د خپل ژوند بچ کولو دپاره هر څۀ ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11910, 'Job 2:5', 'Job', 2, 5, '&nbsp;خو کۀ د هغۀ په بدن باندې تکليف راولې، نو هغه به ستا په حضور کښې په تا لعنت ووائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11911, 'Job 2:6', 'Job', 2, 6, '&nbsp;نو مالِک خُدائ شېطان ته وفرمائيل، ”بلکل ټيک ده هغه ستا په اختيار کښې دے خو هغه ژوندے پرېږده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11912, 'Job 2:7', 'Job', 2, 7, '&nbsp;نو شېطان د مالِک خُدائ د حضور نه لاړو او په ايُوب باندې يې د سر نه تر پښو پورې خرابې دانې راوخېژولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11913, 'Job 2:8', 'Job', 2, 8, '&nbsp;نو ايُوب د خاورې د مات لوښى يوه ټوټه واخستله او ځان يې ورباندې ګرولو او په ايرو باندې کښېناستو چې خپل خفګان څرګند کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11914, 'Job 2:9', 'Job', 2, 9, '&nbsp;نو ايُوب ته خپلې ښځې ووئيل، ”تر اوسه پورې تۀ لا په خپل صداقت قائم يې؟ په خُدائ پاک لعنت ووايه او مړ شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11915, 'Job 2:10', 'Job', 2, 10, '&nbsp;خو هغۀ خپلې ښځې ته وفرمائيل، ”تۀ خو لکه د کم عقلې ښځې په شان خبرې کوې، ولې مونږ به د خُدائ د طرفه صرف ښۀ څيزونه اخلو څۀ او هيڅکله به ترې نه بد نۀ اخلو؟“ خو د دې ټولو خبرو باوجود ايُوب د خُدائ پاک خِلاف يوه خبره هم ونۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11916, 'Job 2:11', 'Job', 2, 11, '&nbsp;نو چې کله د ايُوب درې ملګرى د هغه ټولو مصيبتونو نه خبر شول کوم چې په ايُوب باندې راغلى وُو، نو هغوئ هر يو د خپل خپل کور نه روان شول هغوئ په يو ځائ ايُوب له ورغلل چې د تسلۍ خبرې ورته وکړى. د هغوئ نومونه دا دى، اليفز تيمانى، بِلداد شوحى، او ضوفر نعماتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11917, 'Job 2:12', 'Job', 2, 12, '&nbsp;کله چې هغوئ ايُوب د لرې نه وليدلو، نو هغه د پېژندګلو نه وتے وو خو چې کله يې وپېژندو نو په چغو چغو يې وژړل، هغوئ د غم نه خپلې چُوغې وشلولې او په سر باندې يې خاورې واچولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11918, 'Job 2:13', 'Job', 2, 13, '&nbsp;هغوئ د هغۀ سره په زمکه باندې اووۀ شپې او اووۀ ورځې ناست وُو او يو کس هم هغۀ ته يوه خبره هم ونۀ کړه، ځکه چې هغوئ ته پته وه چې د هغۀ تکليف ډېر زيات دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11919, 'Job 3:1', 'Job', 3, 1, '&nbsp;د هغې نه پس ايُوب خبرې شروع کړې او چې په کومه ورځ باندې هغه پېدا شوے وو په هغې يې لعنت ووئيلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11920, 'Job 3:2', 'Job', 3, 2, '&nbsp;ايُوب وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11921, 'Job 3:3', 'Job', 3, 3, '&nbsp;”هغه ورځ دې تباه شى چې په کومه ورځ باندې زۀ پېدا شوے وم او چې په کومه شپه زۀ د مور په ګېډه شوے وم نو هغه شپه د‌ې لعنتى شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11922, 'Job 3:4', 'Job', 3, 4, '&nbsp;هغه ورځ دې تکه توره شى. لوئ خُدائ پاک دې پرې نظر نۀ اچوى، او رڼا دې پرې نۀ راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11923, 'Job 3:5', 'Job', 3, 5, '&nbsp;توره دې شى او تکه توره تيارۀ دې پرې راشى. وريځې دې ورباندې پاتې شى، د هغه ورځې تيارۀ دې دا ويروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11924, 'Job 3:6', 'Job', 3, 6, '&nbsp;تکه توره تيارۀ دې هغه شپه قابو کړى. هغه دې بيا هيڅکله د کال په ورځو کښې نۀ شى شمېرلے او په يوه مياشت کښې دې هم حِساب نۀ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11925, 'Job 3:7', 'Job', 3, 7, '&nbsp;او هغه شپه دې شنډه شى، په هغه شپه کښې دې هيڅ خوشحالى نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11926, 'Job 3:8', 'Job', 3, 8, '&nbsp;لعنت ويونکى دې هم په هغه ورځ لعنت ووائى، هغه څوک چې په سمندرى بلاګانو راويښولو کښې ماهِر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11927, 'Job 3:9', 'Job', 3, 9, '&nbsp;د دې د سحر ستورى دې تور شى، هغه دې د رڼا په طمع وى، خو مِلاو دې ورته نۀ شى، دا دې په سحر کښې د نمر شُغلې ونۀ وينى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11928, 'Job 3:10', 'Job', 3, 10, '&nbsp;لعنت دې وى په هغه شپه چې زما د مور حمل يې کېدو ته پرېښودو، او زۀ يې د دې ټولو مصيبتونو دپاره پېدا کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11929, 'Job 3:11', 'Job', 3, 11, '&nbsp;زۀ د پېدا کېدو په وخت ولې مړ نۀ شوم، او د زيږېدنې په وخت مردار ولې نۀ شوم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11930, 'Job 3:12', 'Job', 3, 12, '&nbsp;زۀ ولې د مور په غېږ کښې وم، هغې ولې ما له سينه راکړې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11931, 'Job 3:13', 'Job', 3, 13, '&nbsp;کۀ زۀ مړ وے نو خاموش به وے، زۀ به اودۀ وے، او زۀ به په آرام وے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11932, 'Job 3:14', 'Job', 3, 14, '&nbsp;د دُنيا د بادشاهانو او وزيرانو سره چې هغوئ د خپل ځان دپاره محلونه جوړ کړى وُو او اوس ترې نه کنډرات جوړ دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11933, 'Job 3:15', 'Job', 3, 15, '&nbsp;يا د شهزادګانو سره چې د هغوئ سره سرۀ زر وى، چې هغوئ خپل کورونه د سپينو زرو نه ډک کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11934, 'Job 3:16', 'Job', 3, 16, '&nbsp;يا زۀ د مړ پېدا شوى ماشوم په شان ولې ښخ نۀ شوم، د هغه ماشوم په شان چې رڼا يې هيڅکله نۀ وى ليدلې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11935, 'Job 3:17', 'Job', 3, 17, '&nbsp;چرته چې بدعمله خلق تکليف نۀ شى جوړولے، او ستړى خلق په آخر کښې آرام مومى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11936, 'Job 3:18', 'Job', 3, 18, '&nbsp;چرته چې قېديان هم په آرام وى، او هغوئ د ظالمانو آواز نۀ اورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11937, 'Job 3:19', 'Job', 3, 19, '&nbsp;غټ او واړۀ هلته دى، او غلامان د خپلو نېکانو نه آزاد دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11938, 'Job 3:20', 'Job', 3, 20, '&nbsp;چې څوک په مصيبت کښې وى هغه ولې ژوندى پرېږدى، او چې د چا ژوند د غمونو نه ډک وى نو هغۀ له ژوند ولې ورکوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11939, 'Job 3:21', 'Job', 3, 21, '&nbsp;چې څوک مرګ غواړى، هغۀ له نۀ راځى، هغوئ دا د پټې خزانې نه زيات لټوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11940, 'Job 3:22', 'Job', 3, 22, '&nbsp;کله چې هغوئ مړۀ شى نو ډېر خوشحاله شى، او چې کله قبر له لاړ شى نو هغوئ خوشحاله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11941, 'Job 3:23', 'Job', 3, 23, '&nbsp;چې څوک لار نۀ شى ليدلے نو هغۀ له رڼا ولې ورکولے شى، څوک چې خُدائ پاک راګېر کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11942, 'Job 3:24', 'Job', 3, 24, '&nbsp;ځکه چې د روټۍ په ځائ ما ته اسويلى راځى، او زما فريادونه د اوبو په شان تويَولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11943, 'Job 3:25', 'Job', 3, 25, '&nbsp;چې زۀ د څۀ نه يرېږم نو هغه په ما راځى، او چې د څۀ نه يرېږم نو هغه په ما راغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11944, 'Job 3:26', 'Job', 3, 26, '&nbsp;زۀ په آرام نۀ يم او نۀ زۀ خاموش يم، زۀ پرېشانه يم، خو زما مصيبت نۀ ختميږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11945, 'Job 4:1', 'Job', 4, 1, '&nbsp;بيا تيمانى اليفز په جواب کښې ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11946, 'Job 4:2', 'Job', 4, 2, '&nbsp;”کۀ څوک تا ته يوه خبره وکړى نو تۀ به خفه کېږې څۀ؟ خو د خبرو نه څوک ځان منع کولے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11947, 'Job 4:3', 'Job', 4, 3, '&nbsp;ګوره، تا ډېرو خلقو ته ښودنه کړې ده، تا کمزورى لاسونه تکړه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11948, 'Job 4:4', 'Job', 4, 4, '&nbsp;ستا ډاډګيرنې خلق په خپلو پښو ودرولى دى. کوم خلق چې په غورزېدو وُو هغوئ يې نېغ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11949, 'Job 4:5', 'Job', 4, 5, '&nbsp;خو اوس مصيبت په تا باندې راغلے دے او تۀ وارخطا يې، چې دا تا له درنزدې شى نو تۀ پرېشانه شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11950, 'Job 4:6', 'Job', 4, 6, '&nbsp;ستا اعتماد د خُدائ پاک يره نۀ ده څۀ، او ستا نېک عمل تا له اُميد نۀ درکوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11951, 'Job 4:7', 'Job', 4, 7, '&nbsp;اوس دا سوچ وکړه، داسې څوک شته چې بې‌ګناه وى او تباه شى؟ او داسې څوک صادق شته چې تباه شوے وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11952, 'Job 4:8', 'Job', 4, 8, '&nbsp;چې څومره ما ته پته ده، چې چا دا بې‌اِنصافى کړې ده چې چا مصيبت کَرلے دے، نو هغۀ مصيبت رېبلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11953, 'Job 4:9', 'Job', 4, 9, '&nbsp;د خُدائ پاک د ساه په ذريعه هغوئ سزا موندلې ده، او د هغۀ د غصې د زور په وجه هغوئ تباه شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11954, 'Job 4:10', 'Job', 4, 10, '&nbsp;بدعمله د ازمرى په شان غړمبيږى، خو خُدائ پاک هغوئ غلى کوى او غاښونه يې ماتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11955, 'Job 4:11', 'Job', 4, 11, '&nbsp;لکه چې تکړه ازمرے د ښکار د کمى په وجه هلاکيږى، او د دې واړۀ بچى خوارۀ وارۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11956, 'Job 4:12', 'Job', 4, 12, '&nbsp;اوس ما ته پټ پټ يو خبر راغلو، او زما غوږُونو ته د دې غلے شان آواز راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11957, 'Job 4:13', 'Job', 4, 13, '&nbsp;په نيمه شپه ما يو يروونکے خوب وليدو، دا په هغه وخت وو چې خلق په دروند خوب اودۀ وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11958, 'Job 4:14', 'Job', 4, 14, '&nbsp;يره او لړزان په ما باندې راغلل، چې دې زما ټول بدن وخوځولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11959, 'Job 4:15', 'Job', 4, 15, '&nbsp;يو روح زما په وړاندې تېر شو او زما په بدن وېښتۀ نېغ ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11960, 'Job 4:16', 'Job', 4, 16, '&nbsp;هغه روح ولاړ وو، خو ما ته پته نشته چې دا څۀ وُو. زما د سترګو په وړاندې يو شکل وو، هر څۀ خاموش وُو، بيا ما يو آواز واورېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11961, 'Job 4:17', 'Job', 4, 17, '&nbsp;ولې انسان کولے شى چې د خُدائ پاک په وړاندې صادق شى څۀ؟ ولې انسان د خالِق نه زيات پاک کېدے شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11962, 'Job 4:18', 'Job', 4, 18, '&nbsp;تر دې پورې چې هغه په خپلو خِدمتګارانو باندې هم اعتماد نۀ کوى، او هغه د خپلو فرښتو کار ته هم غلط وائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11963, 'Job 4:19', 'Job', 4, 19, '&nbsp;نو هغه به په انسان باندې څومره کم اعتماد وکړى څوک چې د خاورې نه جوړ وى. نو څوک چې د خاورى نه جوړ وى هغه به د پتنګ په شان په آسانۍ ذرې ذرې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11964, 'Job 4:20', 'Job', 4, 20, '&nbsp;سحر روغ وى او ماښام مړ شى. او څوک هم پرې خبر نۀ شى او د تل دپاره تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11965, 'Job 4:21', 'Job', 4, 21, '&nbsp;د هغوئ نه خپل ټول مال اخستے شوے دے، هغوئ په جاهليت مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11966, 'Job 5:1', 'Job', 5, 1, '&nbsp;آواز وکړه، داسې څوک شته چې تا له جواب درکړى؟ داسې يوه فرښته شته څۀ چې د هغې نه مدد وغواړې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11967, 'Job 5:2', 'Job', 5, 2, '&nbsp;په حقيقت کښې نفرت کم عقل خلق وژنى، او حسد ساده خلق وژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11968, 'Job 5:3', 'Job', 5, 3, '&nbsp;ما دا ليدلى دى چې څۀ کم عقل خلق د لږ وخت دپاره کامياب وى، خو بيا ناڅاپه تباهى ورباندې راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11969, 'Job 5:4', 'Job', 5, 4, '&nbsp;د هغوئ د بچو دپاره به د پناه هيڅ امکان نۀ وى، او داسې به څوک نۀ وى چې په عدالت کښې يې خلاص کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11970, 'Job 5:5', 'Job', 5, 5, '&nbsp;اوږى خلق د کم عقلو فصلونه خورى، کۀ د هغۀ د پټو نه د حِفاظت دپاره ازغى هم تاو وى، لالچى خلق د هغوئ دولت ختم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11971, 'Job 5:6', 'Job', 5, 6, '&nbsp;ځکه چې خفګان د زمکې نه نۀ راځى، او نۀ مصيبت د زمکې نه پېدا کيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11972, 'Job 5:7', 'Job', 5, 7, '&nbsp;خو انسانان د مصيبت دپاره داسې پېدا شوى دى لکه چې د اور بڅرکى بره الوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11973, 'Job 5:8', 'Job', 5, 8, '&nbsp;کۀ زۀ ستا په ځائ وے نو ما به خُدائ پاک لټولے، او خُدائ پاک ته به مې فرياد اورولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11974, 'Job 5:9', 'Job', 5, 9, '&nbsp;هغه داسې لوئ لوئ کارونه کوى چې څوک ورباندې نۀ پوهيږى، هغه بې‌شمېره عجيبه کارونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11975, 'Job 5:10', 'Job', 5, 10, '&nbsp;هغه په زمکه باندې باران ورَوى او هغه پټو ته اوبۀ رالېږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11976, 'Job 5:11', 'Job', 5, 11, '&nbsp;چې څوک غريب وى نو خُدائ پاک يې مالداره کړى، او چې څوک غمژن وى نو خوشحالى ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11977, 'Job 5:12', 'Job', 5, 12, '&nbsp;هغه د چالاکو منصوبې ګډې وډې کړى، نو داسې د هغوئ په لاس کښې هيڅ کاميابى نۀ راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11978, 'Job 5:13', 'Job', 5, 13, '&nbsp;هغه هوښيار د خپلې چالاکۍ په جال کښې راګېروى، او چالاک خلق زر فنا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11979, 'Job 5:14', 'Job', 5, 14, '&nbsp;د ورځې په وخت په هغوئ تيارۀ راشى او د غرمې په وخت داسې تيندکونه خورى لکه چې شپه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11980, 'Job 5:15', 'Job', 5, 15, '&nbsp;خو هغه ضرورتمند خلق د مرګ نه بچ کوى، او د زورَور د زور نه يې بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11981, 'Job 5:16', 'Job', 5, 16, '&nbsp;نو چې غريبانان اُميد ولرى، او د بې‌اِنصافه خلقو خولې بندې کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11982, 'Job 5:17', 'Job', 5, 17, '&nbsp;چې خُدائ پاک څوک ټيک کړى نو هغوئ څومره خوشحاله وى، نو په دې وجه د قادر خُدائ تربيت ته سپک مۀ ګورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11983, 'Job 5:18', 'Job', 5, 18, '&nbsp;کۀ هغه زخمى کول کوى، نو هغه يې مرهم پټۍ هم کوى، کۀ هغه وهل کوى، نو د هغۀ لاسونه يې علاج هم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11984, 'Job 5:19', 'Job', 5, 19, '&nbsp;هغه به تاسو د شپږو افتونو نه بچ کوى، او په اوؤم کښې به تاسو ته هيڅ نقصان نۀ رسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11985, 'Job 5:20', 'Job', 5, 20, '&nbsp;په قحط کښې به هغه تاسو د مرګ نه په بيعه واخلى، او په جنګ کښې به مو د مرګ نه بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11986, 'Job 5:21', 'Job', 5, 21, '&nbsp;تاسو به د سپکو خبرو نه بچ شئ، او چې کله تباهى راځى نو تاسو به نۀ يرېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11987, 'Job 5:22', 'Job', 5, 22, '&nbsp;په تباهۍ او قحط پورې به تاسو خندا کوئ، او د زمکې د ځنګلى ځناورو نه به نۀ يرېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11988, 'Job 5:23', 'Job', 5, 23, '&nbsp;تاسو چې کوم پټى کَرئ نو په هغې کښې به کاڼى نۀ وى، او ځنګلى ځناور به په تاسو حمله نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11989, 'Job 5:24', 'Job', 5, 24, '&nbsp;تاسو ته به پته ولګى چې ستاسو کور محفوظ دے، تاسو به وګورئ چې ستاسو د رَمو نه به هيڅ ورک نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11990, 'Job 5:25', 'Job', 5, 25, '&nbsp;تاسو ته به پته ولګى چې ستاسو اولاد به ډېر وى، داسې بې‌شمېره لکه په زمکه چې واښۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11991, 'Job 5:26', 'Job', 5, 26, '&nbsp;تاسو به خپل قبر ته په بوډاتوب کښې ځئ، لکه چې د فصل ګېډۍ درمند ته په خپل موسم کښې راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11992, 'Job 5:27', 'Job', 5, 27, '&nbsp;ګوره، زمونږه چې د عمر په حقله کومه تجربه ده، دا حقيقت دے. دا نصيحت واوره او په دې باندې عمل وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11993, 'Job 6:3', 'Job', 6, 3, '&nbsp;ځکه چې دا به د سمندر د شګو نه درانۀ وى، نو په دې وجه زما خبرې ګډې وډې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11994, 'Job 6:4', 'Job', 6, 4, '&nbsp;ځکه چې زۀ د قادر خُدائ په غشو باندې لګېدلے يم، د دې زهر زما په بدن کښې خوريږى، د خُدائ پاک افتونه په ما باندې راروان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11995, 'Job 6:5', 'Job', 6, 5, '&nbsp;ولې زۀ د شکايت کولو حق نۀ لرم؟ ولې ځنګلى خرونه او غوَيى آواز نۀ کوى څۀ چې کله هغوئ خوراک نۀ لرى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11996, 'Job 6:6', 'Job', 6, 6, '&nbsp;چې څۀ څيز بې‌خونده وى نو هغه د مالګې نه بغېر خوړلے شى څۀ، يا د هګۍ په سپينو کښې څۀ مزه شته؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11997, 'Job 6:7', 'Job', 6, 7, '&nbsp;کله چې زۀ دې ته وګورم نو زما لوږه ختمه شى، په داسې خوراک زۀ بيمارېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11998, 'Job 6:8', 'Job', 6, 8, '&nbsp;کاش چې زما خواست منظور شى، او خُدائ پاک زما خواهش پوره کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11999, 'Job 6:9', 'Job', 6, 9, '&nbsp;زړۀ مې غواړى چې تباه مې کړى، او چې هغه خپل لاس راوږد کړى او ما ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12000, 'Job 6:10', 'Job', 6, 10, '&nbsp;دا به زما دپاره تسلى وى، زۀ به په بې‌رحمه درد کښې هم خوشحاله يم، ځکه چې ما به بيا هم د مقدسې هستۍ د خبرو نه اِنکار نۀ وى کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');